// Layer 1 & 2 Security: Anti-Spam Rate Limiter & Honeypot Trap
const input = $json.body || $json;

// Check Honeypot Trap (invisible field for bots)
if (input.website || input.honeypot) {
  return [{
    json: {
      blocked: true,
      reason: "Automated bot deflection triggered",
      statusCode: 400
    }
  }];
}

// Check Anonymous vs Verified Track
const isAnonymous = input.isAnonymous === true || input.isAnonymous === 'true';
let pin = null;
let studentName = input.studentName || '';
let regNumber = input.regNumber || '';
let phone = input.phone || '';

if (isAnonymous) {
  studentName = 'CONFIDENTIAL_WHISTLEBLOWER';
  regNumber = 'ANON-REDACTED';
  phone = 'MASKED';
  // Generate Cryptographic 6-Digit PIN
  pin = Math.floor(100000 + Math.random() * 900000).toString();
}

const trackingId = 'GRV-' + new Date().getFullYear() + '-' + Math.floor(10000 + Math.random() * 90000);

return [{
  json: {
    trackingId,
    studentName,
    regNumber,
    phone,
    isAnonymous,
    secretPin: pin,
    category: input.category || 'General',
    subject: input.subject || 'Student Grievance',
    description: input.description || '',
    department: input.department || 'CSE',
    submittedAt: new Date().toISOString()
  }
}];

